-- Security & Access Governance 1.0.0 — masking and row access policies
--
-- Classification: restricted.
-- 5 column(s) carry values that must not be read in the
-- clear by a consumer who is not entitled to them.
--
-- Policies are attached to the published views only. The curated and raw
-- layers are never in a share (§13.4).
--
-- Generated by the Observability & FinOps Platform. Review before running.
-- The platform does not execute this script; a human does (R2, R8).

USE ROLE SNOWOBS_PUBLISHER;

CREATE MASKING POLICY IF NOT EXISTS OBSERVABILITY.PUBLISHED.MP_SNOWOBS_SENSITIVE
  AS (value STRING) RETURNS STRING ->
    CASE
      WHEN IS_ROLE_IN_SESSION('SNOWOBS_CONSUMER') THEN value
      ELSE SHA2(value, 256)
    END
  COMMENT = 'Hashes identifying values for roles outside the product consumer role; the hash stays joinable.';

ALTER VIEW OBSERVABILITY.PUBLISHED.V_ACCESS_GOVERNANCE_LOGIN MODIFY COLUMN USER
  SET MASKING POLICY OBSERVABILITY.PUBLISHED.MP_SNOWOBS_SENSITIVE;
ALTER VIEW OBSERVABILITY.PUBLISHED.V_ACCESS_GOVERNANCE_LOGIN MODIFY COLUMN CLIENT_IP
  SET MASKING POLICY OBSERVABILITY.PUBLISHED.MP_SNOWOBS_SENSITIVE;
ALTER VIEW OBSERVABILITY.PUBLISHED.V_ACCESS_GOVERNANCE_GRANT MODIFY COLUMN GRANTEE
  SET MASKING POLICY OBSERVABILITY.PUBLISHED.MP_SNOWOBS_SENSITIVE;
ALTER VIEW OBSERVABILITY.PUBLISHED.V_ACCESS_GOVERNANCE_GRANT MODIFY COLUMN GRANTED_BY
  SET MASKING POLICY OBSERVABILITY.PUBLISHED.MP_SNOWOBS_SENSITIVE;
ALTER VIEW OBSERVABILITY.PUBLISHED.V_ACCESS_GOVERNANCE_USER MODIFY COLUMN USER
  SET MASKING POLICY OBSERVABILITY.PUBLISHED.MP_SNOWOBS_SENSITIVE;

CREATE ROW ACCESS POLICY IF NOT EXISTS OBSERVABILITY.PUBLISHED.RAP_SNOWOBS_RESTRICTED
  AS (row_owner STRING) RETURNS BOOLEAN ->
    IS_ROLE_IN_SESSION('SNOWOBS_CONSUMER')
  COMMENT = 'Restricted product: only the product consumer role sees rows.';

ALTER VIEW OBSERVABILITY.PUBLISHED.V_ACCESS_GOVERNANCE_LOGIN
  ADD ROW ACCESS POLICY OBSERVABILITY.PUBLISHED.RAP_SNOWOBS_RESTRICTED
  ON (USER);
ALTER VIEW OBSERVABILITY.PUBLISHED.V_ACCESS_GOVERNANCE_GRANT
  ADD ROW ACCESS POLICY OBSERVABILITY.PUBLISHED.RAP_SNOWOBS_RESTRICTED
  ON (GRANTEE);
ALTER VIEW OBSERVABILITY.PUBLISHED.V_ACCESS_GOVERNANCE_USER
  ADD ROW ACCESS POLICY OBSERVABILITY.PUBLISHED.RAP_SNOWOBS_RESTRICTED
  ON (USER);
